import SocialState from './SocialState';
import { post } from '../common/api';
export function subscribeRealtime(channel, callback) {
  if (!SocialState.config.realtime?.enabled) return () => {};
  let centrifuge = null;
  let cancelled = false;
  post('/social/realtime/token', {
    channel
  }).then(async response => {
    if (cancelled) return;
    const {
      Centrifuge
    } = await import(/* webpackChunkName: 'forum/centrifuge', webpackMode: 'lazy-once' */ 'centrifuge');
    const tokens = response.data;
    centrifuge = new Centrifuge(tokens.url, {
      token: tokens.token
    });
    const subscription = centrifuge.newSubscription(tokens.channel, {
      token: tokens.subscriptionToken
    });
    subscription.on('publication', context => callback(context.data));
    subscription.subscribe();
    centrifuge.connect();
  }).catch(() => {
    // Polling fallback is handled by the component.
  });
  return () => {
    cancelled = true;
    try {
      centrifuge?.disconnect();
    } catch (e) {
      // no-op
    }
  };
}