import app from 'flarum/forum/app';
export class SocialApiError extends Error {
  constructor(message, status) {
    super(message);
    this.status = status;
  }
}
function apiUrl(path) {
  return app.forum.attribute('apiUrl') + path;
}
function extractError(error) {
  const detail = error?.response?.errors?.[0]?.detail;
  if (typeof detail === 'string' && detail !== '') {
    try {
      return decodeURIComponent(detail);
    } catch (e) {
      return detail;
    }
  }
  if (error?.status === 401) {
    return app.translator.trans('cengizkemec-social.forum.errors.auth_required');
  }
  if (error?.status === 403) {
    return app.translator.trans('cengizkemec-social.forum.errors.forbidden');
  }
  return error?.message || app.translator.trans('cengizkemec-social.forum.errors.generic');
}
export async function request(method, path, body) {
  const options = {
    method,
    url: apiUrl(path),
    errorHandler: () => {}
  };
  if (body !== undefined) {
    options.body = body;
  }
  try {
    return await app.request(options);
  } catch (error) {
    throw new SocialApiError(extractError(error), Number(error?.status || 0));
  }
}
export function get(path, params = {}) {
  const parts = [];
  const append = (key, value) => {
    if (value === undefined || value === null || value === '') return;
    parts.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(value)));
  };
  Object.keys(params).forEach(key => {
    const value = params[key];
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      Object.keys(value).forEach(nested => append(`${key}[${nested}]`, value[nested]));
    } else {
      append(key, value);
    }
  });
  const query = parts.length ? '?' + parts.join('&') : '';
  return request('GET', path + query);
}
export function post(path, body = {}) {
  return request('POST', path, body);
}
export function patch(path, body = {}) {
  return request('PATCH', path, body);
}
export function del(path, body) {
  return request('DELETE', path, body);
}
export function uploadFile(path, file, onProgress) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    const data = new FormData();
    data.append('file', file);
    xhr.open('POST', apiUrl(path));
    xhr.setRequestHeader('X-CSRF-Token', app.session.csrfToken);
    if (xhr.upload && onProgress) {
      xhr.upload.onprogress = event => {
        if (event.lengthComputable) onProgress(Math.round(event.loaded / event.total * 100));
      };
    }
    xhr.onload = () => {
      let payload = null;
      try {
        payload = xhr.responseText ? JSON.parse(xhr.responseText) : null;
      } catch (e) {
        payload = null;
      }
      if (xhr.status >= 200 && xhr.status < 300) {
        resolve(payload);
      } else {
        const detail = payload?.errors?.[0]?.detail;
        reject(new SocialApiError(detail || app.translator.trans('cengizkemec-social.forum.errors.upload_failed'), xhr.status));
      }
    };
    xhr.onerror = () => reject(new SocialApiError(app.translator.trans('cengizkemec-social.forum.errors.generic'), 0));
    xhr.send(data);
  });
}
flarum.reg.add('cengizkemec-social', 'common/api', { SocialApiError: SocialApiError,get: get,post: post,patch: patch,del: del,uploadFile: uploadFile, });