import app from 'flarum/forum/app';
import { get } from '../../common/api';
import { roomUrl } from '../utils';
let cachedData = null;
let pendingRequest = null;

/**
 * Discord/FoF-Blog style channel directory for Flarum's own index sidebar.
 * Categories contain both voice rooms and standalone text channels.
 */
export default class ForumSocialMenu {
  data = cachedData;
  loaded = Boolean(cachedData);
  oninit() {
    if (!cachedData) {
      cachedData = window.__socialRoomsData || null;
    }
    this.data = cachedData;
    this.loaded = Boolean(cachedData);
    if (cachedData) return;
    pendingRequest = pendingRequest || get('/social/rooms').then(response => {
      cachedData = response.data || null;
      window.__socialRoomsData = cachedData;
      return cachedData;
    });
    pendingRequest.then(data => {
      this.data = data;
      this.loaded = true;
      m.redraw();
    }).catch(() => {
      this.loaded = true;
      m.redraw();
    });
  }
  view() {
    if (!app.forum.attribute('socialEnabled') || !app.forum.attribute('socialForumMenu')) {
      return null;
    }
    if (!this.loaded) {
      this.data = window.__socialRoomsData || this.data;
      if (!this.data) {
        return m('section', {
          className: 'SocialForumMenu SocialForumMenu--loading'
        }, m('i', {
          className: 'fas fa-spinner fa-spin'
        }));
      }
    }
    if (!this.data) return null;
    const rooms = this.data.rooms || [];
    const channels = this.data.channels || [];
    const categories = (this.data.categories || []).map(category => ({
      category,
      rooms: rooms.filter(room => Number(room.categoryId) === Number(category.id)),
      channels: channels.filter(channel => Number(channel.categoryId) === Number(category.id))
    })).filter(group => group.rooms.length || group.channels.length);
    const other = {
      category: {
        id: 'other',
        name: app.translator.trans('cengizkemec-social.forum.nav.other_rooms'),
        icon: 'fas fa-door-open'
      },
      rooms: rooms.filter(room => !room.categoryId),
      channels: channels.filter(channel => !channel.categoryId)
    };
    const groups = [...categories, other].filter(group => group.rooms.length || group.channels.length);
    if (!groups.length) return null;
    return m('section', {
      className: 'SocialForumMenu'
    }, [m('div', {
      className: 'SocialForumMenu-head'
    }, [m('span', {}, [m('i', {
      className: 'fas fa-comments'
    }), ' ', app.translator.trans('cengizkemec-social.forum.forum_menu.title')]), m('a', {
      className: 'SocialForumMenu-all',
      href: app.route('social.rooms')
    }, app.translator.trans('cengizkemec-social.forum.forum_widget.all'))]), groups.map(group => m('div', {
      className: 'SocialForumMenu-category'
    }, [m('div', {
      className: 'SocialForumMenu-categoryTitle'
    }, [group.category.icon ? m('i', {
      className: group.category.icon
    }) : null, m('span', {}, group.category.name)]), ...group.rooms.map(room => m('a', {
      className: 'SocialForumMenu-link',
      href: roomUrl(room)
    }, [m('i', {
      className: room.icon || (room.isVoice ? 'fas fa-volume-high' : 'fas fa-hashtag')
    }), m('span', {}, room.name)])), ...group.channels.map(channel => m('a', {
      className: 'SocialForumMenu-link SocialForumMenu-link--text',
      href: app.route('social.channel', {
        id: channel.id
      })
    }, [m('i', {
      className: 'fas fa-hashtag'
    }), m('span', {}, channel.name)]))]))]);
  }
}
flarum.reg.add('cengizkemec-social', 'forum/components/ForumSocialMenu', ForumSocialMenu);