import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import SocialState from './SocialState';
function isSelf(user) {
  return Boolean(user && app.session.user && Number(user.id?.()) === Number(app.session.user.id?.()));
}
function openSocialProfile() {
  const username = app.session.user?.username?.();
  if (username) {
    m.route.set(app.route('social.profile', {
      username
    }));
  }
}
function openVoiceSettings() {
  const show = () => app.modal.show(() => import(/* webpackChunkName: 'forum/components/VoiceSettingsModal', webpackMode: 'lazy-once' */ './components/VoiceSettingsModal'));
  if (SocialState.loaded) {
    show();
  } else {
    SocialState.load().finally(show);
  }
}

/**
 * Add Social profile and voice-settings entry points to Flarum's own profile
 * and account settings pages, so members do not have to discover the Social
 * shell before editing their Social identity.
 */
export function installProfileIntegration() {
  extend('flarum/forum/components/UserPage', 'navItems', function (items) {
    if (!app.forum?.attribute('socialEnabled') || !isSelf(this.user)) return;
    items.add('socialProfile', m(Button, {
      className: 'Button',
      icon: 'fas fa-user-pen',
      onclick: openSocialProfile
    }, app.translator.trans('cengizkemec-social.forum.profile.social_profile')), 55);
    items.add('socialVoice', m(Button, {
      className: 'Button',
      icon: 'fas fa-headset',
      onclick: openVoiceSettings
    }, app.translator.trans('cengizkemec-social.forum.voice.settings_title')), 54);
  });
  extend('flarum/forum/components/SettingsPage', 'accountItems', function (items) {
    if (!app.forum?.attribute('socialEnabled') || !isSelf(this.user)) return;
    items.add('socialProfile', m(Button, {
      className: 'Button',
      icon: 'fas fa-user-pen',
      onclick: openSocialProfile
    }, app.translator.trans('cengizkemec-social.forum.profile.social_profile')), 85);
    items.add('socialVoice', m(Button, {
      className: 'Button',
      icon: 'fas fa-headset',
      onclick: openVoiceSettings
    }, app.translator.trans('cengizkemec-social.forum.voice.settings_title')), 84);
  });
}flarum.reg.addChunkModule('520', '162', 'cengizkemec-social', 'forum/components/VoiceSettingsModal');